class Solution:
    def moveOneBall(self, arr: List[int]) -> bool:
        # Check if the first element is greater than or equal to its next element
        if arr[0] >= arr[1]:
            return False

        # Iterate through the array from the second element onwards
        for i in range(1, len(arr)):
            # If the current element is less than the next element, we need to perform a right shift
            if arr[i] < arr[i+1]:
                # Perform a right shift operation and check if the new array is sorted
                arr = arr[:i] + [arr[i]] + arr[i+1:]
                if self.moveOneBall(arr):
                    return True
        return False
