from collections import deque

def bf(planet1, planet2):
    # Check if both planet names are valid
    if planet1 not in ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus"]:
        return ()

    if planet2 not in ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus"]:
        return ()

    # Initialize a deque with the planets' orbits
    orbits = deque(sorted(["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus"]))

    # Add the first planet's orbit to the deque
    orbits.appendleft(planet1)

    # Iterate through the remaining planets
    for i in range(len(orbits) - 1):
        # If the current planet's orbit is before the second planet's orbit, add it to the deque
        if orbits[i] < orbits[i + 1]:
            orbits.insert(i + 1, orbits.pop(i))

    # Return the deque containing only the planets within the specified range
    return tuple(orbits)


